//! The named ids of the language's string table (Language.dll's, src/Empire Earth/Language/Language.rc): names
//! from the English text (`IDS_<id>` where the text is not nameable), the keys of the planned YAML string file.
//! `ee/EEStringIDs.h` keeps the ones the C++ uses; the test below checks they equal these.
#![allow(non_upper_case_globals)]

macro_rules! string_ids {
    ($($name:ident = $value:literal,)*) => {
        $(pub const $name: u32 = $value;)*
        /// Every id by name, in the table's order.
        pub const ALL: &[(&str, u32)] = &[$((stringify!($name), $value),)*];
    };
}

/// An id by its name (`"IDS_ARIAL"`).
pub fn by_name(name: &str) -> Option<u32> {
    ALL.iter().find(|(n, _)| *n == name).map(|(_, v)| *v)
}

